verus! {
    #[verifier::spec]
    fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
        // Ensure that the input array is not modified
        let n = a.len();
        let (mut left, mut right) = (Vec::new(), Vec::new());

        // Split the array into two parts
        if n == 0 {
            // If the array is empty, return two empty arrays
            return (left, right);
        } else if n == 1 {
            // If the array has one element, we can only return one empty array
            left.push(a[0]);
            return (left, right);
        } else {
            // For arrays with length greater than 1, we split it into two non-empty parts
            let mid = n / 2; // Choose a midpoint for splitting
            left.extend_from_slice(&a[0..mid]);
            right.extend_from_slice(&a[mid..n]);
        }

        // Ensure the properties are satisfied
        assert!(left.len() + right.len() == n); // The sum of lengths must equal the original length
        assert!(left.len() < n); // Left array must be strictly shorter than original
        assert!(right.len() < n); // Right array must be strictly shorter than original

        // Ensure that concatenation reconstructs the original array
        let mut reconstructed = Vec::new();
        reconstructed.extend_from_slice(&left);
        reconstructed.extend_from_slice(&right);
        assert!(reconstructed == a); // The concatenation must equal the original array

        (left, right)
    }
}